CONFIRMATION_SHA256 = '06863938d60dc0369d18ab01324462d1606c9497f09661976302a15d59b0fa4f'
RECEIPT_SHA256 = 'b1a866ab37a4ae27efdaacc2aa4155e42d1ae58990593aa0accc9af9ee160ab2'

def encoded(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2)+'\n').encode()

def sha(content):
    return hashlib.sha256(content).hexdigest()

def exact(actual, expected, label):
    # JSON encoding distinguishes bool from int; Python equality alone does not.
    if encoded(actual) != encoded(expected):
        raise ValueError(label)

def safe_relative(rel):
    if type(rel) is not str or not rel or '\\' in rel or any(x in ('','.','..') for x in rel.split('/')):
        raise ValueError('unsafe relative path')
    return Path(rel)

def safe_file(root, rel):
    p=root/safe_relative(rel)
    if not p.is_file() or p.is_symlink() or p.absolute()!=p.resolve() or not p.resolve().is_relative_to(root.resolve()):
        raise ValueError('missing or unsafe file '+rel)
    return p.read_bytes()

def verify_history(root, policy):
    bindings=policy['baseline_sha256_bindings']
    exact(sha(encoded(bindings)),BASELINE_SHA256,'accepted1539 manifest')
    exact(len(bindings),1539,'accepted file count')
    history={}
    for rel,digest in bindings.items():
        content=safe_file(root,rel)
        if rel=='CHANGELOG.md':
            prefix=CHANGELOG_PREFIX.encode()
            exact(content[:len(prefix)].hex(),prefix.hex(),'new329 CHANGELOG prefix')
            exact(len(content),policy['accepted_changelog_size_bytes']+len(prefix),'additive CHANGELOG length')
            content=content[len(prefix):]
        exact(sha(content),digest,'accepted artifact drift '+rel)
        history[rel]=content
    return history

def validate_confirmation(confirmation, receipt):
    exact(sha(encoded(confirmation)),CONFIRMATION_SHA256,'external confirmed328 boundary')
    exact(sorted(receipt),['encoding','original_display_sha256','original_display_size_bytes','text'],'receipt schema')
    exact(receipt['encoding'],'utf8-json-text','receipt encoding')
    raw=receipt['text'].encode()
    exact(sha(raw),RECEIPT_SHA256,'original complete328 receipt')
    exact(len(raw),95315,'original complete328 receipt size')
    exact(receipt['original_display_sha256'],RECEIPT_SHA256,'receipt SHA metadata')
    exact(receipt['original_display_size_bytes'],95315,'receipt size metadata')
    lines=receipt['text'].splitlines()
    exact(sum(x.startswith('PASS: ') for x in lines),1320,'ordered1320 returned passes')
    exact(lines.count('Result: PASS (1320 passes, 0 failures)'),1,'full1320 summary')
    if '[main 9d62a1f]' not in receipt['text'] or 'e49029b..9d62a1f  main -> main' not in receipt['text']:
        raise ValueError('missing returned328 commit/push')
    return True

def validate_plan(plan, retained, freeze, cross, failure):
    exact(plan,EXPECTED_PLAN,'new repository-only329 route, schema and authority boundaries')
    exact(retained,EXPECTED_RETAINED,'unwaived obligations and original source views')
    for key in ['freeze_version','successor_contract_bindings','frozen_contract_views','contract_view_fields',
                'seven_requirements_bindings','preserved_cross_obligations','future_proof_register',
                'remaining_operational_blockers','inherited_blocker_disposition','crossclosure_counts']:
        exact(retained[key],freeze[key],'exact frozen328 '+key)
    exact(retained['effect_domains'],cross['vector_ids']['effects'],'all30 source effect domains')
    exact(retained['designed_edges'],cross['catalogue_edges'],'every source designed edge')
    exact(retained['authority_windows'],cross['authority_windows'],'all nine source rights windows')
    exact(retained['independent_conformance_plan'],failure['conformance_plan'],'both52 independent source cases')
    exact(len(retained['future_proof_register']),46,'all46 retained proofs')
    exact(len(retained['seven_requirements_bindings']),7,'all seven capabilities')
    exact(len(retained['preserved_cross_obligations']),10,'all ten cross obligations')
    exact(len(retained['effect_domains']),30,'all30 domains')
    exact(len(retained['authority_windows']),9,'all nine windows')
    for row in retained['future_proof_register']:
        exact(row['source_proof']['status'],'required-not-proven','no proof waiver')
        exact(row['operational_proven'],False,'no actual proof claim')
        exact(row['actual_evidence'],None,'no invented live evidence')
    return True

def evaluate_private_gate(value):
    exact(sorted(value),['checkpoint','origin','requested_step','returned_step','scope'],'gate schema')
    exact(value['origin'],'synthetic-private-fixture','private origin')
    exact(value['scope'],'repository-preparation-only','private gate scope')
    for k in ['requested_step','returned_step']:
        if type(value[k]) is not int:
            raise ValueError('integer stage required')
    if value['requested_step'] not in range(330,339):
        raise ValueError('outside future candidate route')
    keys=['applied','complete_acceptance','exact_commit','push_successful','worktree_clean','HEAD_matches_origin']
    exact(sorted(value['checkpoint']),sorted(keys),'complete checkpoint fields')
    if any(type(x) is not bool for x in value['checkpoint'].values()):
        raise ValueError('checkpoint flags must be bool')
    return dict(model_repository_preparation_eligible=
                value['returned_step']==value['requested_step']-1 and all(value['checkpoint'].values()),
                actual_dispatch_authorized=False,actual_grant_issued=False,actual_grant_reused=False,
                actual_operational_conformance=False,actual_host_closure=False)

def run_historical(history):
    with tempfile.TemporaryDirectory(prefix='step329-exact328-') as directory:
        snapshot=Path(directory)/'slack-update'
        for rel,content in history.items():
            p=snapshot/safe_relative(rel);p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(content)
        result=subprocess.run(['bash',str(snapshot/'tests/reference'/('test-'+PRIOR+'-harness.sh'))],capture_output=True)
        lines=result.stdout.decode().splitlines()
        if result.returncode or sum(x.startswith('PASS: ') for x in lines)!=1320 or lines.count('Result: PASS (1320 passes, 0 failures)')!=1:
            sys.stderr.buffer.write(result.stdout+result.stderr)
            raise ValueError('full exact1320 predecessor acceptance failed')
        return result.stdout

def main(root,out):
    if not root.is_dir() or root.absolute()!=root.resolve():
        raise ValueError('unsafe repository root')
    for rel,digest in OWN_HASHES.items():
        exact(sha(safe_file(root,rel)),digest,'changed329 artifact '+rel)
    load=lambda suffix:json.loads(safe_file(root,FIXTURE+'/'+BASE+suffix))
    policy=load('-policy.json');history=verify_history(root,policy)
    freeze=json.loads(history[FIXTURE+'/'+PRIOR+'-freeze.json'])
    cross=json.loads(history[freeze['crossclosure_binding']['path']])
    failure=json.loads(history[freeze['successor_contract_bindings']['326']['path']])
    validate_plan(load('-plan.json'),load('-retained-obligations.json'),freeze,cross,failure)
    validate_confirmation(load('-checkpoint-confirmation.json'),load('-step328-user-acceptance.json'))
    if not out.is_dir() or out.absolute()!=out.resolve():
        raise ValueError('output must exist without symlink ancestors')
    suffixes=['-policy.json','-plan.json','-checkpoint-confirmation.json','-step328-user-acceptance.json','-roadmap.tsv','-retained-obligations.json']
    payloads={BASE+s:safe_file(root,FIXTURE+'/'+BASE+s) for s in suffixes}
    logname=BASE+'-predecessor-test.log'
    if any((out/n).exists() or (out/n).is_symlink() for n in list(payloads)+[logname]):
        raise ValueError('occupied private output; no overwrite')
    payloads[logname]=run_historical(history)
    exact({r:sha(c) for r,c in verify_history(root,policy).items()},
          {r:sha(c) for r,c in history.items()},'history changed during private validation')
    for rel,digest in OWN_HASHES.items():
        exact(sha(safe_file(root,rel)),digest,'329 input changed during validation')
    created=[]
    try:
        for name,content in payloads.items():
            with (out/name).open('xb') as stream:
                created.append(out/name);stream.write(content)
    except BaseException:
        for p in reversed(created):p.unlink()
        raise
    print('exact_step328_acceptance\tPASS (1320 passes, 0 failures)')
    print('step329_candidate_refinement_resume_planning_status\tPASS')
    print('planned_repository_step_range\t329-338')
    print('last_confirmed_strong_safe_pause_step\t328')
    print('strong_safe_pause\tno-user329-acceptance-pending')
    print('all46_proofs_and52_cases_retained_not_executed\tyes')
    print('actual_dispatch_or_publication_authorized\tno')
    print('operational_readiness\tno')

if __name__=='__main__':
    try:main(Path(sys.argv[1]).absolute(),Path(sys.argv[2]).absolute())
    except (ValueError,OSError,KeyError,TypeError) as exc:
        print('ERROR: '+str(exc),file=sys.stderr);sys.exit(1)
